class Solution {
public:
    int maxMoves(vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();

        vector<int> dp(m, 0);
        int ans = 0;

        for (int col = 1; col < n; col++) {
            vector<int> newDp(m, -1);
            bool anyReachable = false;
            for (int row = 0; row < m; row++) {
                for (int dr : {-1, 0, 1}) {
                    int prevRow = row + dr;
                    if (prevRow >= 0 && prevRow < m && dp[prevRow] != -1 
                        && grid[prevRow][col - 1] < grid[row][col]) {
                        newDp[row] = max(newDp[row], dp[prevRow] + 1);
                        anyReachable = true;
                    }
                }
            }
            dp = move(newDp);
            if (!anyReachable) break;
            for (int row = 0; row < m; row++) {
                ans = max(ans, dp[row]);
            }
        }

        return ans;
    }
};
